textContent:
Given an even number N, the task is to find two Fibonacci numbers whose sum can be represented as N. There may be several combinations possible. Print only first such pair. If there is no solution then print -1.Examples:  



Input: N = 90 Output: 1, 89 Explanation: The first pair with whose sum is equal to 90 is {1, 89}Input: N = 74 Output: -1  



 



Approach: The idea is to use hashing to precompute and store the Fibonacci numbers, and then check if a pair is a Fibonacci value in O(1) time.Below is the implementation of the above approach:  



            CPP

    // C++ program to find two
// Fibonacci numbers whose
// sum can be represented as N

#include <bits/stdc++.h>
using namespace std;

// Function to create hash table
// to check Fibonacci numbers
void createHash(set<int>& hash,
                int maxElement)
{

    // Storing the first two numbers
    // in the hash
    int prev = 0, curr = 1;
    hash.insert(prev);
    hash.insert(curr);

    // Finding Fibonacci numbers up to N
    // and storing them in the hash
    while (curr < maxElement) {
        int temp = curr + prev;
        hash.insert(temp);
        prev = curr;
        curr = temp;
    }
}

// Function to find the Fibonacci pair
// with the given sum
void findFibonacciPair(int n)
{
    // creating a set containing
    // all fibonacci numbers
    set<int> hash;
    createHash(hash, n);

    // Traversing all numbers
    // to find first pair
    for (int i = 0; i < n; i++) {

        // If both i and (N - i) are Fibonacci
        if (hash.find(i) != hash.end()
            && hash.find(n - i) != hash.end()) {

            // Printing the pair because
            // i + (N - i) = N
            cout << i << ", "
                 << (n - i) << endl;
            return;
        }
    }

    // If no fibonacci pair is found
    // whose sum is equal to n
    cout << "-1\n";
}

// Driven code
int main()
{
    int N = 90;

    findFibonacciPair(N);

    return 0;
}


            Java

    // Java program to find two 
// Fibonacci numbers whose 
// sum can be represented as N 
import java.util.*;

class GFG{ 

// Function to create hash table 
// to check Fibonacci numbers 
static void createHash(HashSet<Integer> hash, 
                int maxElement) 
{ 

    // Storing the first two numbers 
    // in the hash 
    int prev = 0, curr = 1; 
    hash.add(prev); 
    hash.add(curr); 

    // Finding Fibonacci numbers up to N 
    // and storing them in the hash 
    while (curr < maxElement) { 
        int temp = curr + prev; 
        hash.add(temp); 
        prev = curr; 
        curr = temp; 
    } 
} 

// Function to find the Fibonacci pair 
// with the given sum 
static void findFibonacciPair(int n) 
{ 
    // creating a set containing 
    // all fibonacci numbers 
    HashSet<Integer> hash = new HashSet<Integer>(); 
    createHash(hash, n); 

    // Traversing all numbers 
    // to find first pair 
    for (int i = 0; i < n; i++) { 

        // If both i and (N - i) are Fibonacci 
        if (hash.contains(i)
            && hash.contains(n - i)) { 

            // Printing the pair because 
            // i + (N - i) = N 
            System.out.print(i+ ", "
                + (n - i) +"\n"); 
            return; 
        } 
    } 

    // If no fibonacci pair is found 
    // whose sum is equal to n 
    System.out.print("-1\n"); 
} 

// Driven code 
